<?php require __DIR__.'/guard.php'; ?>
<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><title>Отзывы — ПрофиСпорт</title><style>:root{--y:#f2c94c;--bg:#f5f5f3;--tx:#202124;--muted:#747a80;--line:#e3e3df;--green:#19964a;--red:#b93429;--page:1040px}*{box-sizing:border-box}body{margin:0;font:15px/1.4 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;background:var(--bg);color:var(--tx)}.top{background:linear-gradient(135deg,#454b51,#2f3439);color:#fff;position:sticky;top:0}.topin{max-width:var(--page);margin:auto;min-height:64px;padding:0 14px;display:flex;align-items:center;justify-content:space-between}.brand{font-weight:900;font-size:21px}.brand i{font-style:normal;color:var(--y)}.back{color:#fff;text-decoration:none;background:#ffffff17;border:1px solid #ffffff26;padding:10px 13px;border-radius:10px}main{max-width:var(--page);margin:18px auto;padding:0 14px 60px}.tools{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.tools button,.review button{border:0;border-radius:10px;padding:11px 14px;font-weight:800;background:var(--y)}.tools .secondary,.review .secondary{background:#e9e9e5}.review{background:#fff;border:1px solid var(--line);border-radius:16px;padding:16px;margin:12px 0}.review h3{margin:0 0 4px}.meta{color:var(--muted);font-size:13px}.stars{color:#d2a600;font-size:18px}.actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:12px}.actions input{width:130px;padding:10px;border:1px solid var(--line);border-radius:9px}.ok{color:var(--green)}.err{color:var(--red)}.empty{background:#fff;border:1px solid var(--line);border-radius:16px;padding:22px}.activeTab{background:#454b51!important;color:#fff!important}</style></head><body><header class="top"><div class="topin"><div class="brand">Профи<i>Спорт</i></div><a class="back" href="index.php">← Админка</a></div></header><main><h1>Отзывы</h1><div class="tools"><button data-status="pending" class="activeTab">На модерации</button><button data-status="approved" class="secondary">Опубликованные</button><button data-status="rejected" class="secondary">Отклонённые</button></div><div id="summary"></div><div id="list"></div></main><script>let csrf='',status='pending';const $=s=>document.querySelector(s),esc=s=>String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));async function auth(){const r=await fetch('../server/api.php?action=me',{cache:'no-store'});if(!r.ok){location.href='index.php';return false}const j=await r.json();csrf=j.csrf||'';return true}async function load(){summary.textContent='Загрузка…';const r=await fetch('../api/review-moderation.php?status='+status,{cache:'no-store'}),j=await r.json();if(!r.ok||!j.ok){summary.textContent='Не удалось загрузить отзывы.';return}summary.textContent=`Отзывов: ${j.items.length}`;list.innerHTML=j.items.length?j.items.map(x=>`<article class="review" data-id="${x.id}"><h3>${esc(x.product_name||'Товар')}</h3><div class="meta">${esc(x.customer_name||'Покупатель')} · ${esc(x.customer_email||'')} · ${esc(x.created_at||'')}</div><div class="stars">${'★'.repeat(Number(x.rating)||0)}</div><p>${esc(x.review_text)}</p>${status==='pending'?`<div class="actions"><label>Бонус за отзыв <input class="bonus" type="number" min="0" value="0"></label><button class="approve">Опубликовать</button><button class="reject secondary">Отклонить</button></div>`:''}<div class="msg"></div></article>`).join(''):'<div class="empty">Здесь пока пусто.</div>';bind()}function bind(){document.querySelectorAll('.review').forEach(card=>{card.querySelector('.approve')?.addEventListener('click',()=>moderate(card,'approve'));card.querySelector('.reject')?.addEventListener('click',()=>moderate(card,'reject'))})}async function moderate(card,action){const msg=card.querySelector('.msg'),bonus=Number(card.querySelector('.bonus')?.value||0);msg.textContent='Сохраняю…';const r=await fetch('../api/review-moderation.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({review_id:Number(card.dataset.id),action,bonus})}),j=await r.json();if(!r.ok||!j.ok){msg.innerHTML='<span class="err">Ошибка сохранения.</span>';return}msg.innerHTML='<span class="ok">Готово.</span>';setTimeout(load,300)}document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{status=b.dataset.status;document.querySelectorAll('[data-status]').forEach(x=>x.classList.toggle('activeTab',x===b));load()});(async()=>{if(await auth())load()})()</script></body></html>